package app.still.planner;
import android.app.*;import android.appwidget.*;import android.content.*;import android.widget.*;import java.text.*;import java.util.*;import org.json.*;
public class TodayWidget extends AppWidgetProvider {
 protected String kind(){return "today";}
 public void onUpdate(Context c,AppWidgetManager m,int[] ids){update(c,m,ids,kind());}
 static void update(Context c,AppWidgetManager m,int[] ids,String kind){Store store=new Store(c);try{String raw=store.load();JSONObject root=raw.isEmpty()?null:new JSONObject(raw);String body="Your day, gently.",action="Open Still →",today=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());if(root!=null){if(kind.equals("today")){JSONArray tasks=root.getJSONArray("tasks");StringBuilder sb=new StringBuilder();int n=0;for(int i=0;i<tasks.length()&&n<4;i++){JSONObject t=tasks.getJSONObject(i);String due=t.optString("dueDate");if(!"done".equals(t.optString("status"))&&!t.optBoolean("archived")&&!due.isEmpty()&&due.compareTo(today)<=0){sb.append("○  ").append(t.optString("title")).append("\n");n++;}}body=n==0?"You're all caught up.":sb.toString().trim();action="Add a task +";}else if(kind.equals("focus")){JSONObject t=root.optJSONObject("timer");int seconds=root.getJSONObject("preferences").optInt("focusMinutes",25)*60;if(t!=null)seconds=t.optBoolean("running")?(int)Math.max(0,(t.optLong("endAt")-System.currentTimeMillis())/1000):t.optInt("remaining");body=String.format(Locale.US,"%02d:%02d",seconds/60,seconds%60)+"\nOne thing at a time";action="Open focus →";}else{JSONArray hs=root.getJSONArray("habits");int total=0,done=0;for(int i=0;i<hs.length();i++){JSONObject h=hs.getJSONObject(i);if(!ReminderReceiver.habitDue(h,today))continue;total++;JSONArray logs=h.getJSONArray("completions");int count=0;for(int j=0;j<logs.length();j++)if(today.equals(logs.getJSONObject(j).optString("date")))count++;if(count>=h.optInt("target",1))done++;}body=done+" / "+total+" completed\nSmall steps, every day";action="Open habits →";}}for(int id:ids){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget);v.setTextViewText(R.id.widget_title,"STILL · "+kind.toUpperCase(Locale.US));v.setTextViewText(R.id.widget_body,body);v.setTextViewText(R.id.widget_action,action);Intent i=new Intent(c,MainActivity.class).putExtra("action",kind.equals("today")?"new-task":kind.equals("focus")?"focus":"habits");PendingIntent p=PendingIntent.getActivity(c,kind.hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|0x04000000);v.setOnClickPendingIntent(R.id.widget_root,p);m.updateAppWidget(id,v);}}catch(Exception ignored){}finally{store.close();}}
 static void refreshAll(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);update(c,m,m.getAppWidgetIds(new ComponentName(c,TodayWidget.class)),"today");update(c,m,m.getAppWidgetIds(new ComponentName(c,FocusWidget.class)),"focus");update(c,m,m.getAppWidgetIds(new ComponentName(c,HabitWidget.class)),"habits");}
}
